 "content": "def transform(grid):
    """Replace embedded solid rectangular color fields with 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The examples contain planted uniform rectangles at least 5x5. A 4x5
    # planted block is also allowed; this catches the smaller instance shape.
    # Mark cells participating in any such solid monochrome rectangle.
    marked = [[False] * w for _ in range(h)]
    min_h, min_w = 4, 5
    for r0 in range(h - min_h + 1):
        for c0 in range(w - min_w + 1):
            color = grid[r0][c0]
            # Enumerate rectangle bottoms; extend width only while all rows
            # remain the same color. This detects exact solid blocks.
            valid_width = [True] * (w - c0)
            for r1 in range(r0, h):
                row = grid[r1]
                for dx in range(w - c0):
                    if valid_width[dx] and row[c0 + dx] != color:
                        valid_width[dx] = False
                height = r1 - r0 + 1
                if height >= min_h:
                    run = 0
                    for dx, valid in enumerate(valid_width):
                        if valid:
                            run += 1
                            if run >= min_w:
                                # The current same-color rectangle has height
                                # >= min_h and width >= min_w.
                                for rr in range(r0, r1 + 1):
                                    for cc in range(c0 + dx - run + 1, c0 + dx + 1):
                                        marked[rr][cc] = True
                        else:
                            run = 0
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
